function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 25, 25, 0, 2 * Math.PI);
  ctx.stroke();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 40);
  ctx.lineTo(W/2 - 25, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 40);
  ctx.lineTo(W/2 + 25, H/2 - 60);
  ctx.stroke();

  // tilting head
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t) * 0.5);
  ctx.beginPath();
  ctx.arc(0, -25, 25, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 10, H/2 - 50 + Math.sin(t) * 10, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 10, H/2 - 50 + Math.sin(t) * 10, 5, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
